from pathlib import Path
import re,json,hashlib
root=Path(__file__).resolve().parents[2];out=root/'.dev-evidence/remote-preview'
out.mkdir(exist_ok=True)
source=(root/'firmware/web/index.html').read_text(encoding='utf-8')
header=(root/'firmware/include/web_page.h').read_text(encoding='utf-8')
embedded=header.split('R"BTCWEB(',1)[1].rsplit(')BTCWEB";',1)[0]
assert source==embedded
reference_path=root/'界面模拟/index.html'
if not reference_path.exists():reference_path=root/'资料/界面模拟/index.html'
reference=reference_path.read_text(encoding='utf-8-sig')
css=re.search(r'<style>([\s\S]*?)</style>',reference)[1]
assert css in source
assert 'state.runtime' not in source and 'OledV2.' not in source and 'const CODES' not in source
config={'revision':1,'deviceId':'slave-test','masterId':'master-01','prefix':'pair-test','targetMac':'C0:11:22:33:44:55','generation':1,'wifiSsid':'Test AP','broker':'mqtt.example.com','mqttUser':'test','caPem':'','apn':'','modemCa':'btclone-ca','tls':True,'labPlaintext':False,'fixed':False,'sleep':False,'batteryMode':False,'strict':True,'simulate':True,'port':8883,'rollOffset':25,'rollLength':4,'rollMirror':42,'scanEvery':86400,'scanSeconds':20,'uploadEvery':86400,'workSeconds':180,'displayLock':False,'recoveryRestart':False,'retryAttempts':3,'retryBaseSeconds':60,'retryMaxSeconds':900,'cooldownSeconds':21600,'connectSeconds':30,'restartBatches':3,'apSeconds':300,'screenSeconds':30,'staleSeconds':1209600,'usableMah':1800,'sleepMa':5,'activeMa':60,'modemMa':200,'fixedAdv':'0201061AFF4C00021500112233445566778899AABBCCDDEEFF11223344C5','fixedRsp':'020A000303A5FD0E16A5FD6411223344C0001122334408094D426561636F6E','fixedPdu':'ADV_IND','slots':[{'start':480,'end':495},{'start':1225,'end':1235}]}
(out/'local-fixture.json').write_text(json.dumps(config),encoding='utf-8')
fixture='''const originalFetch=window.fetch.bind(window);const ready=originalFetch('/local-fixture.json').then(r=>r.json());const params=new URLSearchParams(location.search);const fixtureRole=params.get('role')||'slave';window.fetch=async(url,opts={})=>{const c={...await ready,deviceId:fixtureRole+'-test',sleep:fixtureRole==='master',batteryMode:fixtureRole==='master',fixed:params.get('fixed')==='true'};let data;if(url.endsWith('/config'))data=opts.method==='POST'?{message:'QA模拟：参数提交完成（非设备）'}:c;else if(url.endsWith('/action'))data={message:'QA模拟：请求已记录（非设备）'};else data={role:fixtureRole,deviceId:c.deviceId,masterId:c.masterId,firmwareVersion:'0.3.3-dev',configRevision:1,wifi:true,wifiIp:'192.0.2.1',wifiTest:'连接成功',ap:true,apIp:'192.168.4.1',cellular:fixtureRole==='master',mqtt:true,subscribed:fixtureRole==='slave',modemStatus:'4G 已注网',modemShutdownConfirmed:false,storageOk:true,rolling:'11223344',rollingCopiesMatch:true,binding:{masterId:c.masterId,prefix:c.prefix,targetMac:c.targetMac,generation:1},mode:fixtureRole==='master'?'采集上传':c.fixed?'固定模式':'从设备模式',cacheState:c.fixed?'固定 raw，不随 MQTT 更新':'已缓存',lastObserved:'11-14 08:00:00',receivedAt:'11-14 08:00:01',lastUpload:'11-14 08:00:00',lastTimeSync:'11-14 08:00:00',lastAutomaticRestart:'时间未知',nextTimeSyncSeconds:72000,bleAdvertising:fixtureRole==='slave',scan:'已完整抓取目标',scanActive:false,upload:'上传成功（PUBACK）',power:fixtureRole==='master'?'电池供电（电量粗估）':'外接供电',batteryEstimatePercent:fixtureRole==='master'?82:null,timeValid:true,nextWindow:1794659100,activeWindowEnd:0,powerSaving:fixtureRole==='master',freeHeap:120000,uptimeSeconds:3600,networkRecovery:{waitSeconds:0,attemptsInBatch:0,failedBatches:0},nearby:[{mac:c.targetMac,rssi:-64}],logs:['QA：仅浏览器合成数据，非设备实测','已接收主端快照，原始字节保持不变'],snapshot:{seq:42,rssi:-64,adv_hex:c.fixedAdv,scan_rsp_hex:c.fixedRsp}};return {ok:true,json:async()=>structuredClone(data)}};'''
(out/'local-fixture.js').write_text(fixture,encoding='utf-8')
probe='''setTimeout(()=>{const p=new URLSearchParams(location.search),tab=p.get('tab')||'overview';document.querySelector('[data-tab="'+tab+'"]')?.click();const doc=document.documentElement;const result={fixture:true,width:innerWidth,clientWidth:doc.clientWidth,overflow:doc.scrollWidth>doc.clientWidth,nav:Array.from(document.querySelectorAll('[data-tab]')).map(b=>b.textContent),active:Array.from(document.querySelectorAll('[data-panel]')).filter(e=>!e.hidden).map(e=>e.dataset.panel),cards:document.querySelectorAll('.stat').length,diagCollapsed:!document.querySelector('#state').closest('details').open,palette:getComputedStyle(document.documentElement).getPropertyValue('--accent').trim(),buttonRadius:getComputedStyle(document.querySelector('#save-button')).borderRadius};const r=document.createElement('div');r.id='local-qa';r.hidden=true;r.textContent=JSON.stringify(result);document.body.append(r)},1800);'''
(out/'local-probe.js').write_text(probe,encoding='utf-8')
page=embedded.replace('<script>','<script src="/local-fixture.js"></script><script>',1).replace('</body>','<script src="/local-probe.js"></script></body>')
(out/'local.html').write_text(page,encoding='utf-8')
refscript='''setTimeout(()=>{const p=new URLSearchParams(location.search),role=p.get('role')||'slave',tab=p.get('tab')||'overview';document.querySelector('[data-action=role][data-role="'+role+'"]')?.click();document.querySelector('[data-action=tab][data-tab="'+(tab==='radio'?(role==='master'?'bluetooth':'simulation'):tab)+'"]')?.click();const b=document.querySelector('.browser');if(b){b.querySelector('.browser-bar')?.remove();document.body.replaceChildren(b);document.body.style.margin='0';b.style.borderRadius='0';b.style.border='0';const r=document.createElement('div');r.hidden=true;r.id='ref-qa';r.textContent=JSON.stringify({width:innerWidth,nav:Array.from(b.querySelectorAll('.app-nav button')).map(x=>x.textContent),palette:getComputedStyle(document.documentElement).getPropertyValue('--accent').trim()});document.body.append(r)}},700);'''
(out/'reference-probe.js').write_text(refscript,encoding='utf-8')
(out/'reference.html').write_text(reference.replace('</body>','<script src="/reference-probe.js"></script></body>'),encoding='utf-8')
for role in ('master','slave'):
    for tab in (('overview','network','radio','device') if role=='slave' else ('overview','schedule')):
        for fixed in ([False,True] if tab=='radio' else [False]):
            key=role+'-'+tab+('-fixed' if fixed else '')
            q=f'role={role}&tab={tab}'+('&fixed=true' if fixed else '')
            wrapper='''<!doctype html><meta charset="utf-8"><style>body{margin:0;background:#e8eeeb;font:12px system-ui}.pair{display:flex;gap:20px;justify-content:center}iframe{border:0;width:390px;height:1700px;background:#fff}h2{font:14px system-ui;margin:15px 0;text-align:center}</style><div class="pair"><div><h2>已认可预览 · 合成数据</h2><iframe id="reference" src="reference.html?'''+q+'''"></iframe></div><div><h2>固件内嵌页面 · 合成API验收</h2><iframe id="actual" src="local.html?'''+q+'''"></iframe></div></div><script>setTimeout(()=>{const d=document.querySelector('#actual').contentDocument;const r=document.createElement('pre');r.hidden=true;r.id='comparison-qa';r.textContent=d.querySelector('#local-qa')?.textContent||'missing';document.body.append(r)},3500)</script>'''
            (out/('compare-'+key+'.html')).write_text(wrapper,encoding='utf-8')
(root/'.dev-evidence/local-ui-source-check.json').write_text(json.dumps({'approved_preview_sha256':hashlib.sha256(reference.encode()).hexdigest(),'approved_css_embedded_exactly':True,'source_matches_embedded_header':True,'canonical_page_sha256':hashlib.sha256(source.encode()).hexdigest(),'bytes':len(source.encode()),'preview_runtime_not_copied':True,'real_device_acceptance':False},indent=2),encoding='utf-8')
print('Prepared compiled-header versus approved-preview visual QA, synthetic data only.')
